import{_ as a,o as i,c as o,a5 as s}from"./chunks/framework.BwlBv862.js";const m=JSON.parse('{"title":"Visão geral do desenvolvimento de plugins","description":"","frontmatter":{"title":"Visão geral do desenvolvimento de plugins","docId":"developer.plugins.index","translationKey":"developer.plugins.index","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"690689449dfe463405cff0ea6b3a33979249bbe68c598ee7e8ca862eedd704dc","translationRevision":"fbb4afd7a336108b047205fadbd8e54fa6bb5dc04ac64dbf3216e26051c37c93","order":240},"headers":[],"relativePath":"pt/developer/plugins/index.md","filePath":"pt/developer/plugins/index.md","lastUpdated":1794611623000}'),t={name:"pt/developer/plugins/index.md"};function n(r,e,d,l,p,c){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-development-overview" tabindex="-1">Visão geral do desenvolvimento de plugins <a class="header-anchor" href="#plugin-development-overview" aria-label="Permalink to &quot;Visão geral do desenvolvimento de plugins {#plugin-development-overview}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Escolha o menor limite de plugin que atenda à sua integração. O TikTools descobre pacotes de execução em raízes integradas, de usuário e de desenvolvimento; adicionar um pacote não exige recompilar um plugin pelo nome dentro do host. Use o devkit/SDK correspondente e um perfil privado de desenvolvimento antes de testar efeitos.</p><h2 id="follow-the-authoring-path" tabindex="-1">Siga o caminho de autoria <a class="header-anchor" href="#follow-the-authoring-path" aria-label="Permalink to &quot;Siga o caminho de autoria {#follow-the-authoring-path}&quot;">​</a></h2><ol><li>Comece pelo <a href="./quickstart.html">guia inicial</a> para gerar a estrutura, validar e compilar um pacote isolado.</li><li>Escolha um <a href="./runtimes.html">ambiente de execução</a> conforme dependências nativas e confiança, não apenas pela extensão do arquivo.</li><li>Declare <a href="./permissions-ui.html">permissões e interface</a> para que o host possa revisar efeitos e renderizar a configuração.</li><li>Use <a href="./packaging-registry.html">empacotamento e registro</a> para integridade, confiança no publicador e política de atualização.</li></ol><p>A autoridade Rust de baixo nível é <code>crates/tiktools-plugin-api</code>: validação de manifestos, protocolo e contratos de interface. <code>crates/tiktools-plugin-sdk</code> oferece a superfície Rust de autoria; <code>packages/plugin-sdk</code> contém auxiliares TypeScript e o <a href="https://github.com/nglmercer/TikTools-app/blob/remake/packages/plugin-sdk/plugin.schema.json" target="_blank" rel="noreferrer">esquema do editor</a>. O carregamento do ambiente de execução pertence a <code>crates/tiktools-plugin-loader</code>, não ao frontend.</p><h2 id="understand-contributions" tabindex="-1">Entenda as contribuições <a class="header-anchor" href="#understand-contributions" aria-label="Permalink to &quot;Entenda as contribuições {#understand-contributions}&quot;">​</a></h2><p>Uma ação solicita um efeito por um resultado tipado. Fontes de eventos publicam acionadores; observadores recebem envelopes de domínio estáveis <code>{topic,data}</code> com entrega limitada. Processadores adicionam evidências sem efeitos em <code>event.intel</code>, com prazos, mesclagem determinística e isolamento de integridade. Configurações/ações declarativas permitem ao host renderizar configurações comuns. Uma página personalizada compilada usa um broker restrito de plugins em seu próprio quadro/janela; seu script nunca se torna parte do runtime Vue principal.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>Essas são verificações específicas do host/SDK, não validação de um pacote externo arbitrário.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Caminhos nativo, de processo, declarativo e <code>napi-vm</code> baseado em QuickJS estão implementados. WASM é uma opção de runtime sem mecanismo ativo de uso geral nas compilações normais. Integrações de exemplo ficam no <a href="https://github.com/nglmercer/plugins-example-tiktools" target="_blank" rel="noreferrer">repositório plugins-example-tiktools</a> separado; nomes de código em documentos antigos não as tornam recursos incluídos no produto.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para falha de descoberta, inspecione compatibilidade do manifesto, precedência das raízes, destino e caminho de entrada. Para uma intenção negada, inspecione capacidades declaradas e concedidas em vez de contornar o host. Uma inicialização incerta deve ser reconciliada antes da substituição. Limites nativos/de processo mantêm restrições de confiança do sistema operacional; o nome do runtime sozinho nunca estabelece uma sandbox.</p>`,14)])])}const h=a(t,[["render",n]]);export{m as __pageData,h as default};
